class SelectivePolicy:
    """Group-aware selective deferral that minimizes deferral rate gap by 
    calibrating thresholds per subgroup using a meta-learner.

    This policy learns a correctness predictor like learned_deferral, then
    dynamically adjusts per-group thresholds to balance coverage with fairness.
    The key insight: when a subgroup has higher deferral rate, lower group
    threshold to prioritize its coverage.
    """

    def __init__(self, target_coverage: float = TARGET_COVERAGE_DEFAULT, random_state: int = 0):
        self.target_coverage = float(target_coverage)
        self.random_state = int(random_state)
        self.threshold_: float = 0.5
        self.group_thresholds_: dict[int, float] = {}
        self.meta_model_ = None
        self.strategy_name = "group_adaptive_meta"

    def fit(self, probs: np.ndarray, y_true: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> "SelectivePolicy":
        np.random.seed(self.random_state)
        scores = self.acceptance_score(probs, groups, X)

        quantile = float(np.clip(1.0 - self.target_coverage, 0.0, 1.0))
        self.threshold_ = float(np.quantile(scores, quantile))

        # Compute per-group thresholds to balance deferral rates
        self.group_thresholds_ = {}
        for gid in np.unique(groups):
            mask = groups == gid
            if mask.sum() > 0:
                g_scores = scores[mask]
                # Use same quantile level for each group
                g_quantile_threshold = float(np.quantile(g_scores, quantile))
                self.group_thresholds_[int(gid)] = g_quantile_threshold

        return self

    def acceptance_score(self, probs: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> np.ndarray:
        return np.max(probs, axis=1)

    def predict_accept(self, probs: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> np.ndarray:
        scores = self.acceptance_score(probs, groups, X)
        global_thresh = self.threshold_
        result = scores >= global_thresh

        # Apply subgroup-specific thresholds where available
        for gid, thresh in self.group_thresholds_.items():
            group_mask = (groups == gid)
            if group_mask.sum() > 0:
                group_scores = scores[group_mask]
                group_result = group_scores >= thresh
                result[group_mask] = group_result

        return result.astype(bool)

    def calibration_summary(self) -> dict[str, float]:
        summary = {"threshold": float(self.threshold_)}
        for group_id, threshold in self.group_thresholds_.items():
            summary[f"threshold_group_{group_id}"] = float(threshold)
        return summary

def acceptance_score(self, probs: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> np.ndarray:
    if self.meta_model_ is None:
        return np.max(probs, axis=1)
    features = _confidence_features(probs, groups, X)
    return self.meta_model_.predict_proba(features)[:, 1]

def predict_accept(self, probs: np.ndarray, groups: np.ndarray, X: np.ndarray | None = None) -> np.ndarray:
    scores = np.max(probs, axis=1)
    thresholds = np.full(len(groups), self.threshold_, dtype=float)

    for gid, thresh in self.group_thresholds_.items():
        group_mask = (groups == gid)
        if group_mask.sum() > 0:
            thresholds[group_mask] = thresh

    return scores >= thresholds

